export class Cursor{constructor(){this.initialized=!1}init(){if(this.initialized)return;if(!document.getElementById("cursor"))return;const e=document.getElementById("cursor");document.addEventListener("mousemove",t=>{e.style.left=t.pageX+"px",e.style.top=t.pageY+"px"}),document.querySelectorAll("a, button, input, textarea, .accordion-title, .filter li").forEach(t=>{t.addEventListener("mouseenter",()=>{e.classList.add("scale-cursor")}),t.addEventListener("mouseleave",()=>{e.classList.remove("scale-cursor")})}),this.initialized=!0,console.log("✅ Custom cursor initialized")}}export default Cursor;